    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            objects.append((color, cells))
    # Match objects by shape size: smaller components are stationary markers;
    # larger components move into the marker group's former orientation/anchor.
    sizes = {}
    for color, cells in objects:
        sizes.setdefault(color, []).append(len(cells))
    for color, cells in objects:
        # All objects with repeated color: the most numerous-sized component acts as a motif;
        # relocate each large shape to the coordinate occupied by the similarly-sized marker.
        if len(sizes[color]) < 2:
            for y,x in cells: out[y][x] = color
            continue
        # In demos each color has one large composite shape and one small component.
        # Preserve components that are not part of a large/small same-color pair.
        if len(cells) == min(sizes[color]):
            continue
        # Move large component to the location of the smallest same-color object.
        target = next(other for col, other in objects if col == color and len(other) == min(sizes[color]))
        minr = min(y for y,x in target); minc = min(x for y,x in target)
        sr = min(y for y,x in cells); sc = min(x for y,x in cells)
        # The orientation is rotated 180 degrees, and anchor at target top-left.
        rel = [(y-sr, x-sc) for y,x in cells]
        mh = max(y for y,x in rel) + 1; mw = max(x for y,x in rel) + 1
        for y,x in rel:
            yy, xx = minr + mh-1-y, minc + mw-1-x
            if 0 <= yy < h and 0 <= xx < w: out[yy][xx] = color
    return out
